import fs from 'node:fs';
import path from 'node:path';

// Release gate: Tenping is intentionally retired from every published LIFE
// route. Checking only the homepage is insufficient: pages are generated by
// multiple build stages and can silently reinsert legacy sponsor markup.
const DIST=path.resolve('dist');
const fail=message=>{throw Error('[no-tenping] '+message);};
const walk=directory=>fs.readdirSync(directory,{withFileTypes:true}).flatMap(entry=>{
  const file=path.join(directory,entry.name);
  return entry.isDirectory()?walk(file):[file];
});
if(!fs.existsSync(path.join(DIST,'index.html')))fail('dist is missing; run npm run build first');
const files=walk(DIST).filter(file=>/\.(?:html|js|mjs|css|json|xml|txt)$/i.test(file));
const domainOrTracking=/(?:tenping|텐핑|iryan\.kr)/i;
const retiredMarkup=/(?:data-affiliate=|data-life-affiliate-layout=|life-affiliate-placement|life-sponsor-collection|life-article-sponsor|life-affiliate-image)/i;
let pages=0;
for(const file of files){
  const relative=path.relative(DIST,file).replaceAll(path.sep,'/');
  const source=fs.readFileSync(file,'utf8');
  if(domainOrTracking.test(source))
    fail('Retired ad vendor URL or identifier appears in '+relative);
  if(file.endsWith('.html')){
    pages++;
    if(retiredMarkup.test(source))
      fail('Retired sponsor markup appears in '+relative);
  }
}
if(pages<150)fail('Unexpectedly few published pages: '+pages);
for(const pathname of ['index.html','car/index.html','support/index.html',
  'support/child-allowance-2026/index.html','car/car-inspection-period/index.html']){
  const html=fs.readFileSync(path.join(DIST,pathname),'utf8');
  if(/<link rel="canonical"/.test(html)===false)
    fail('Canonical metadata missing on '+pathname);
}
const home=fs.readFileSync(path.join(DIST,'index.html'),'utf8');
if((home.match(/data-life-coupang-banner="sitewide-v4"/g)||[]).length!==1)
  fail('Existing publisher Coupang banner unexpectedly changed');
if(!home.includes('google-adsense-account'))
  fail('AdSense publisher verification metadata lost');
console.log('[no-tenping] PASS '+pages+' HTML pages and '+files.length+
  ' text assets have no Tenping scripts, links, tracking IDs or injected sponsor markup; original Coupang and AdSense preserved.');
